document.addEventListener("DOMContentLoaded",function(){if("undefined"==typeof AAE_PAGE_IMPORT)return;const e=document.querySelector(".wrap .wp-heading-inline + .page-title-action");if(!e)return;const t=document.createElement("a");t.id="aae-heading-button",t.className="page-title-action aae-import-page-action",t.href=AAE_PAGE_IMPORT.page_url;const n=document.createElement("img");n.src=AAE_PAGE_IMPORT.logo,n.alt="";const a=document.createElement("span");a.textContent=AAE_PAGE_IMPORT.label,t.appendChild(n),t.appendChild(a),e.after(t)});